import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CfwCq2QB.js";const s="/dev-go-docs/shots/0.2.3/en/light/popup-function.png",i="/dev-go-docs/shots/0.2.3/en/light/options-enhance.png",m=JSON.parse('{"title":"Page enhancements","description":"","frontmatter":{},"headers":[],"relativePath":"en/features/page-enhance.md","filePath":"en/features/page-enhance.md"}'),r={name:"en/features/page-enhance.md"};function h(c,e,l,p,d,u){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="page-enhancements" tabindex="-1">Page enhancements <a class="header-anchor" href="#page-enhancements" aria-label="Permalink to &quot;Page enhancements&quot;">​</a></h1><p>In one line: per-site copy unlocking, per-site control of the selection toolbar and floating dock — all togglable for the current site from the popup&#39;s Features page.</p><p>The Features page is the single entry point for these switches; each affects only the current site and shows its state (&quot;Off on github.com&quot;, &quot;3 sites enabled&quot;, and so on).</p><img src="'+s+'" alt="The popup&#39;s Features page" style="width:60%;display:block;margin-left:auto;margin-right:auto;"><p><em>The popup&#39;s Features page: per-site switches showing the current site&#39;s state.</em></p><h2 id="selection-toolbar" tabindex="-1">Selection toolbar <a class="header-anchor" href="#selection-toolbar" aria-label="Permalink to &quot;Selection toolbar&quot;">​</a></h2><p>Show or hide the selection toolbar on the current site. Online editors and sites with their own selection features are where it gets in the way — turn it off here and every other site keeps it. The list lives under Settings → Selection → &quot;Sites where selection is off&quot;. See <a href="/dev-go-docs/en/features/selection-toolbar.html">Selection toolbar</a>.</p><h2 id="floating-dock" tabindex="-1">Floating dock <a class="header-anchor" href="#floating-dock" aria-label="Permalink to &quot;Floating dock&quot;">​</a></h2><p>Show or hide the dock on the current site; Settings → Page enhancements adds the master switch and the &quot;Sites where the dock is hidden&quot; list. See <a href="/dev-go-docs/en/features/dock.html">Floating dock</a>.</p><h2 id="unlock-copy-on-this-site" tabindex="-1">Unlock copy on this site <a class="header-anchor" href="#unlock-copy-on-this-site" aria-label="Permalink to &quot;Unlock copy on this site&quot;">​</a></h2><p>Some sites block copying, text selection, or the right-click menu. Turn this on and those restrictions lift for the current site.</p><p><strong>Why per-site instead of global</strong>: unlocking everywhere breaks online editors and similar sites, so it only applies to sites you add. Toggle the current site from the popup&#39;s Features page, or manage the list under Settings → Page enhancements → &quot;Sites with copy unlocked&quot; (one domain per line, e.g. <code>www.example.com</code>).</p><h2 id="more" tabindex="-1">More <a class="header-anchor" href="#more" aria-label="Permalink to &quot;More&quot;">​</a></h2><p>The Features page also holds quick entries for the AI assistant and page tools (WebMCP) — see their own pages; &quot;Manage all sites and more features&quot; at the bottom opens settings.</p><img src="'+i+'" alt="Page enhancements settings"><p><em>Settings → Page enhancements: the dock master switch and the copy-unlocked site list.</em></p>',16)])])}const f=t(r,[["render",h]]);export{m as __pageData,f as default};
